import React from 'react';

import { showModal } from '@ui-kit/Modal/modalsHelper';

import FoodActSelectModal from './index';
import { IBaseFoodAct } from '../../../Hiking/@types/hiking.baseTypes';

export const selectFoodActAsync = (title = 'Прием пищи'): Promise<IBaseFoodAct> => {
  return new Promise<IBaseFoodAct>((res, rej) => {
    showModal({
      onClose: rej,
      title,
      size: 'sm',
      children: (close: () => void) => (
        <FoodActSelectModal
          onSelect={(v) => {
            res(v);
            close();
          }}
        />
      ),
    });
  });
};
