import React, { ReactNode } from 'react';

import PiggyBank from '@pohodnik/icons/svg/Commerce/PiggyBank';
import GeoAlt from '@pohodnik/icons/svg/Geo/GeoAlt';
import EggFried from '@pohodnik/icons/svg/RealWorld/EggFried';
import InfoCircleFill from '@pohodnik/icons/svg/Signs/InfoCircleFill';
import JustifyLeft from '@pohodnik/icons/svg/Typography/JustifyLeft';
import Link45Deg from '@pohodnik/icons/svg/UI/Link45Deg';
import Trash from '@pohodnik/icons/svg/UI/Trash';
import clsx from 'clsx';

import ArticleSelectInput from '@apps/Articles/components/ArticleSelectInput';
import { emptyScheduleName } from '@apps/Hiking/@mappers/hikingSchedule.mapper';
import {
  addHikingSchedule,
  updateHikingSchedule,
} from '@apps/Hiking/@services/hikingSchedule.service';
import { IHikingScheduleItem, IHikingTimezone } from '@apps/Hiking/@types/hiking.baseTypes';
import { IHikingData } from '@apps/Hiking/@types/hiking.types';
import { selectFoodActAsync } from '@apps/Recipes/components/FoodActSelectModal/foodActSelectModalHelper';
import { RouteObjectType } from '@apps/Routes/@types/routes.types';
import { selectRouteObjectAsync } from '@apps/Routes/RouteObjectSelectModal/routeObjectSelectModalHelper';
import { getInputDate } from '@helpers/dateHelper';
import { round } from '@helpers/mathHelper';
import { err } from '@helpers/notificationHelper';
import { getGmtShift, getLocalDateByTimezone } from '@helpers/timezoneHelper';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import PohCheckbox from '@ui-kit/Checkbox';
import PohInput from '@ui-kit/Input';
import InputTypes from '@ui-kit/Input/InputTypes';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';

import styles from './style.module.less';
export interface IScheduleEditModalProps {
  hikingData: IHikingData;
  scheduleItem?: IHikingScheduleItem;
  onSave: (scheduleItem: IHikingScheduleItem) => void;
}

const ScheduleEditModal: React.FC<IScheduleEditModalProps> = ({
  hikingData,
  scheduleItem,
  onSave,
}) => {
  const [data, setData] = React.useState<Partial<IHikingScheduleItem>>(scheduleItem ?? {});
  const [withFood, setWithFood] = React.useState(!!data?.foodAct);
  const [withRoute, setWithRoute] = React.useState(!!data?.routeObject);
  const [withDescription, setWithDescription] = React.useState(!!data?.description);
  const [withLink, setWithLink] = React.useState(!!data?.link);
  const [withCost, setWithCost] = React.useState(!!data?.cost);
  const [withArticle, setWithArticle] = React.useState(!!data?.article);

  const [startDateInfo, setStartDateInfo] = React.useState<{
    caption: ReactNode;
    title: string;
  } | null>(null);
  const [finishDateInfo, setFinishDateInfo] = React.useState<{
    caption: ReactNode;
    title: string;
  } | null>(null);

  const nameRef = React.useRef<HTMLInputElement>(null);
  const startDateRef = React.useRef<HTMLInputElement>(null);
  const finishDateRef = React.useRef<HTMLInputElement>(null);

  const getTimezoneTitle = (date: Date, timezoneObj: IHikingTimezone) => {
    return [
      `В расписании всегда фиксируется местное время.`,
      `Дата ${date.toLocaleString()} попадает в диапазон ${timezoneObj.date_in.toLocaleString()} — ${timezoneObj.date_out.toLocaleString()} для которого задан часовой пояс ${timezoneObj.timezone}.`,
      timezoneObj.comment,
      '',
      `В ${Intl.DateTimeFormat().resolvedOptions().timeZone} в это время ${getLocalDateByTimezone(date, timezoneObj.timezone).toLocaleString()}`,
    ].join('\r\n');
  };

  React.useEffect(() => {
    if (!startDateRef.current || !finishDateRef.current) return;
    const handleDateStartChange = () => {
      if (!startDateRef.current || !(startDateRef.current.value.length > 9)) return;
      const date = new Date(startDateRef.current.value);

      const timezoneObj = hikingData?.timezones?.find(
        (tz) => tz.date_in <= date && tz.date_out >= date,
      );

      if (timezoneObj) {
        const shift = getGmtShift(timezoneObj.timezone);
        setStartDateInfo({
          caption: (
            <span className="text-success">
              {timezoneObj.timezone} ({shift})
            </span>
          ),
          title: getTimezoneTitle(date, timezoneObj),
        });
      } else {
        setStartDateInfo(null);
      }
    };
    const handleDateFinishChange = () => {
      if (!finishDateRef.current || !(finishDateRef.current.value.length > 9)) return;
      const date = new Date(finishDateRef.current.value);

      const timezoneObj = hikingData?.timezones?.find(
        (tz) => tz.date_in <= date && tz.date_out >= date,
      );

      if (timezoneObj) {
        const shift = getGmtShift(timezoneObj.timezone);
        setFinishDateInfo({
          caption: (
            <span className="text-success">
              {timezoneObj.timezone} ({shift})
            </span>
          ),
          title: getTimezoneTitle(date, timezoneObj),
        });
      } else {
        setFinishDateInfo(null);
      }
    };

    startDateRef.current.addEventListener('change', handleDateStartChange);
    finishDateRef.current.addEventListener('change', handleDateFinishChange);

    handleDateStartChange();
    handleDateFinishChange();

    return () => {
      if (!startDateRef.current || !finishDateRef.current) return;
      startDateRef.current.removeEventListener('change', handleDateStartChange);
      finishDateRef.current.removeEventListener('change', handleDateFinishChange);
    };
  }, [hikingData.timezones]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const el = e.target as HTMLFormElement;
    const formFields: any = el.elements;

    const name = formFields.name.value;
    const dateStart = formFields.dateStart.value;
    const dateFinish = formFields.dateFinish.value;

    const description = withDescription ? formFields.description.value : null;
    const link = withLink ? formFields.link.value : null;
    const cost = withCost ? formFields.cost.value : null;
    const kkal = withFood ? formFields.foodKkal.value : null;

    const dataForSave: IHikingScheduleItem = {
      id: data?.id ?? 0,
      name,
      start: new Date(dateStart),
      finish: new Date(dateFinish),
      foodAct: data?.foodAct
        ? { ...data.foodAct, kkalCurrent: kkal ?? data?.foodAct?.kkalTarget }
        : undefined,
      routeObject: data?.routeObject ?? undefined,
      currency: null,
      article: data.article ?? null,
      description,
      is_self_sufficiency: !!data.is_self_sufficiency,
      link,
      cost,
    };

    try {
      if (dataForSave.id > 0) {
        await updateHikingSchedule(hikingData.id, dataForSave).then(onSave);
      } else {
        await addHikingSchedule(hikingData.id, dataForSave).then(onSave);
      }
      sessionStorage.setItem(`lastScheduleDate`, getInputDate(dataForSave.finish));
    } catch (err1) {
      err(err1 as Error);
    }
  };

  return (
    <form
      onSubmit={handleSubmit}
      className={clsx(styles.scheduleList, 'd-flex flex-column')}
      style={{ gap: 12 }}
    >
      <PohRow>
        <PohCol sm={6}>
          <PohInput
            required
            type={InputTypes.datetimeLocal}
            defaultValue={data?.start ? getInputDate(data.start) : ''}
            name="dateStart"
            labelClassName="w-100"
            label={
              <div className="d-flex justify-content-between w-100">
                Начало
                {startDateInfo && (
                  <small title={startDateInfo.title}>{startDateInfo.caption}</small>
                )}
              </div>
            }
            className="w-100"
            ref={startDateRef}
          />
        </PohCol>
        <PohCol sm={6}>
          <PohInput
            required
            type={InputTypes.datetimeLocal}
            defaultValue={data?.finish ? getInputDate(data.finish) : ''}
            name="dateFinish"
            label={
              <div className="d-flex justify-content-between w-100">
                Завершение
                {finishDateInfo && (
                  <small title={finishDateInfo.title}>{finishDateInfo.caption}</small>
                )}
              </div>
            }
            labelClassName="w-100"
            className="w-100"
            ref={finishDateRef}
            onDoubleClick={(e) => {
              if (!startDateRef.current) return;
              if (!finishDateRef.current) return;
              e.preventDefault();
              const startDateValue = startDateRef.current.value;
              const finishDateValue = finishDateRef.current.value;
              const startDate = new Date(startDateValue);

              const diffHoursStr = prompt(
                `Можем просто прибавить к дате старта (${startDate.toLocaleString()}) сколько-то часов (Например: 1,5 или 2:45)`,
                round(
                  finishDateValue.length > 10
                    ? (new Date(finishDateValue).getTime() - startDate.getTime()) / 1000 / 60 / 60
                    : 1,
                  1,
                ).toLocaleString(),
              );

              if (!diffHoursStr) return;

              const [hh, mm = '0'] = diffHoursStr.split(':');

              const diffHours = parseFloat(hh.replace(',', '.'));
              const diffMinutes = parseFloat(mm.replace(',', '.'));

              finishDateRef.current.value = getInputDate(
                new Date(
                  startDate.getTime() + diffHours * 60 * 60 * 1000 + diffMinutes * 60 * 1000,
                ),
              );
            }}
          />
        </PohCol>
      </PohRow>
      <PohInput
        autoFocus
        required
        label="Название"
        defaultValue={data?.name || ''}
        autoComplete="data-name"
        name="name"
        className="w-100"
        ref={nameRef}
      />

      <div>
        <PohCheckbox
          checked={data.is_self_sufficiency}
          onChange={(s) => setData((c) => ({ ...c, is_self_sufficiency: s }))}
          label={'Самообеспечение'}
        />
      </div>

      {withRoute && (
        <div className="d-flex align-items-center justify-content-between">
          <div className="w-100 flex-grow-1">
            <PohInput
              readOnly
              autoFocus
              placeholder="Часть трека или точка маршрута"
              value={data?.routeObject?.name || ''}
              autoComplete="data-routeObject"
              name="routeObject"
              onClick={(_e) => {
                if (!hikingData.route.id) return;
                selectRouteObjectAsync(hikingData.route.id).then((ro) => {
                  setData((d) => ({
                    ...d,
                    routeObject: {
                      id: +ro.id,
                      name: ro.name,
                      description: ro.description,
                      distance: ro.type === RouteObjectType.Line ? ro.distance : undefined,
                    },
                    name: d.name?.length ? d.name : ro.name,
                  }));

                  if (
                    nameRef.current &&
                    (!nameRef.current.value.length || nameRef.current.value === emptyScheduleName)
                  ) {
                    nameRef.current.value = ro.name;
                  }
                });
              }}
              label="Трек/Точка"
              className="w-100 flex-grow-1"
            />
          </div>

          {data.routeObject && (
            <PohButton
              icon
              size={ButtonSize.Small}
              onClick={() => {
                setData((d) => ({ ...d, routeObject: undefined }));
              }}
              className="ms-2"
            >
              <Trash />
            </PohButton>
          )}
        </div>
      )}

      {withFood && (
        <PohRow>
          <PohCol sm={8}>
            <PohInput
              required
              readOnly
              value={data?.foodAct?.name || ''}
              placeholder="Тип приема пищи ▼"
              name="foodAct"
              autoFocus
              onClick={(_e) => {
                selectFoodActAsync().then((fa) => {
                  setData((d) => ({ ...d, foodAct: fa, name: d.name?.length ? d.name : fa.name }));
                  if (
                    nameRef.current &&
                    (!nameRef.current.value.length || nameRef.current.value === emptyScheduleName)
                  ) {
                    nameRef.current.value = fa.name;
                  }
                });
              }}
              label="Прием пищи"
              className="w-100"
            />
          </PohCol>
          <PohCol sm={4} className="d-flex align-items-center justify-content-between">
            <PohInput
              required
              type={InputTypes.number}
              min={50}
              max={8000}
              maxLength={4}
              step={1}
              defaultValue={data?.foodAct?.kkalCurrent || data?.foodAct?.kkalTarget || ''}
              title={`${data?.foodAct?.kkalTarget ?? ''}`}
              name="foodKkal"
              label="ккал"
            />
            {data.foodAct && (
              <PohButton
                icon
                size={ButtonSize.Small}
                onClick={() => {
                  setData((d) => ({ ...d, foodAct: undefined }));
                }}
              >
                <Trash />
              </PohButton>
            )}
          </PohCol>
        </PohRow>
      )}

      {withDescription && (
        <PohInput
          autoFocus
          type={InputTypes.textarea}
          label="Подробно"
          placeholder="Введите текст"
          defaultValue={data?.description || ''}
          autoComplete="data-description"
          name="description"
          maxLength={512}
        />
      )}
      {withLink && (
        <PohInput
          type={InputTypes.url}
          label="Ссылка"
          placeholder="Введите url"
          defaultValue={data?.link || ''}
          autoComplete="data-link"
          name="link"
          autoFocus
          maxLength={512}
        />
      )}
      {withCost && (
        <PohInput
          type={InputTypes.number}
          label="Стоимость"
          placeholder="Введите стоимость на 1 участника"
          defaultValue={data?.cost || ''}
          autoComplete="data-cost"
          name="cost"
          min={0}
          autoFocus
        />
      )}
      {withArticle && (
        <div className="d-flex align-items-center justify-content-between">
          <div className="w-100 flex-grow-1">
            <ArticleSelectInput
              label="Статья"
              value={data?.article ?? null}
              onChange={(article) => {
                setData((d) => ({
                  ...d,
                  article: article,
                  name: d.name?.length ? d.name : article.name,
                }));

                if (
                  nameRef.current &&
                  (!nameRef.current.value.length || nameRef.current.value === emptyScheduleName)
                ) {
                  nameRef.current.value = article.name;
                }
              }}
              className="w-100 flex-grow-1"
            />
          </div>

          {data.routeObject && (
            <PohButton
              icon
              size={ButtonSize.Small}
              onClick={() => {
                setData((d) => ({ ...d, id_article: null }));
              }}
              className="ms-2"
            >
              <Trash />
            </PohButton>
          )}
        </div>
      )}

      <footer className="d-flex justify-content-between align-items-center mb-n3 pt-3">
        <aside className={styles.toolbar}>
          {!!hikingData.route.id && (
            <PohButton
              title="Привязать трек или точку с маршрута"
              icon
              size={ButtonSize.Small}
              active={withRoute}
              onClick={() => setWithRoute((c) => !c)}
            >
              <GeoAlt />
            </PohButton>
          )}
          <PohButton
            title="Привязать приём пищи"
            icon
            size={ButtonSize.Small}
            active={withFood}
            onClick={() => setWithFood((c) => !c)}
          >
            <EggFried />
          </PohButton>
          <PohButton
            title="Расширенное описание"
            icon
            size={ButtonSize.Small}
            active={withDescription}
            onClick={() => setWithDescription((c) => !c)}
          >
            <InfoCircleFill />
          </PohButton>
          <PohButton
            title="Ссылка"
            icon
            size={ButtonSize.Small}
            active={withLink}
            onClick={() => setWithLink((c) => !c)}
          >
            <Link45Deg />
          </PohButton>
          <PohButton
            title="Стоимость"
            icon
            size={ButtonSize.Small}
            active={withCost}
            onClick={() => setWithCost((c) => !c)}
          >
            <PiggyBank />
          </PohButton>
          <PohButton
            title="Статья"
            icon
            size={ButtonSize.Small}
            active={withArticle}
            onClick={() => setWithArticle((c) => !c)}
          >
            <JustifyLeft />
          </PohButton>
        </aside>
        <PohButton type="submit" variant={ButtonVariant.Primary}>
          {data?.id ? 'Сохранить' : 'Добавить'}
        </PohButton>
      </footer>
    </form>
  );
};

export default ScheduleEditModal;
