import { IHikingScheduleItem } from '@apps/Hiking/@types/hiking.baseTypes';
import { showModal } from '@ui-kit/Modal';

import ScheduleEditModal, { IScheduleEditModalProps } from './index';
interface IShowScheduleEditModalArgs extends IScheduleEditModalProps {
  title?: string;
}

export const showScheduleEditModal = ({
  scheduleItem,
  onSave,
  hikingData,
  title,
}: IShowScheduleEditModalArgs) => {
  showModal({
    title: title || scheduleItem?.id ? 'Редактирование' : 'Добавление',
    children: (close: () => void) => (
      <ScheduleEditModal
        scheduleItem={scheduleItem}
        hikingData={hikingData}
        onSave={(up) => {
          close();
          onSave?.(up);
        }}
      />
    ),
  });
};
export const showScheduleEditModalAsync = ({
  scheduleItem,
  hikingData,
  title,
}: Omit<IShowScheduleEditModalArgs, 'onSave'>): Promise<IHikingScheduleItem> => {
  return new Promise((res) => {
    showModal({
      title: title || scheduleItem?.id ? 'Редактирование' : 'Добавление',
      children: (close: () => void) => (
        <ScheduleEditModal
          scheduleItem={scheduleItem}
          hikingData={hikingData}
          onSave={(up) => {
            close();
            res(up);
          }}
        />
      ),
    });
  });
};
