import { IBaseFoodAct } from '../@types/hiking.baseTypes';
import { IFoodActDTO } from '../@types/hikingMenu.types';

export const mapFoodActFront = (backData: IFoodActDTO): IBaseFoodAct => {
  return {
    id: +backData.id,
    name: backData.name,
    kkalTarget: backData.norm_kkal ? +backData.norm_kkal : undefined,
  };
};
