import React from 'react';

import GeoAlt from '@pohodnik/icons/svg/Geo/GeoAlt';
import SlashLg from '@pohodnik/icons/svg/Signs/SlashLg';

import { formatDistance } from '@helpers/formatHelper';
import PohAlert from '@ui-kit/Alert';
import PohBadge from '@ui-kit/Badge/Badge';
import PohCheckbox from '@ui-kit/Checkbox';
import PohList from '@ui-kit/List';
import PohLoader from '@ui-kit/Loader';

import { getRouteObjectsAsync } from '../@services/routes.service';
import { IRouteObject, RouteObjectType } from '../@types/routes.types';

export interface IRouteObjectSelectModalProps {
  id_route: number;
  onSelect: (selected: IRouteObject) => void;
  defaultLines?: boolean;
  defaultPoints?: boolean;
  defaultInDistance?: boolean;
  allowTracks?: boolean;
}

const RouteObjectSelectModal: React.FC<IRouteObjectSelectModalProps> = ({
  id_route,
  onSelect,
  defaultLines = true,
  defaultPoints = false,
  defaultInDistance = true,
  allowTracks = true,
}) => {
  const [data, setData] = React.useState<IRouteObject[]>([]);
  const [isLoading, setIsLoading] = React.useState(false);
  const [error, setError] = React.useState('');

  const [isInDistance, setIsInDistance] = React.useState(defaultInDistance);
  const [isLines, setIsLines] = React.useState(defaultLines && allowTracks);
  const [isPoints, setIsPoints] = React.useState(defaultPoints);

  React.useEffect(() => {
    async function fetch() {
      try {
        setIsLoading(true);
        getRouteObjectsAsync(id_route).then(setData);
      } catch (e) {
        setError((e as Error).message);
      } finally {
        setIsLoading(false);
      }
    }
    fetch();
  }, [id_route]);

  if (isLoading) {
    return <PohLoader />;
  }

  if (error.length) {
    return <PohAlert>{error}</PohAlert>;
  }

  const filterFunc = (ro: IRouteObject) => {
    return (
      (!isInDistance || ro.is_in_distance) &&
      ((isLines && ro.type === RouteObjectType.Line) ||
        (isPoints && ro.type === RouteObjectType.Point))
    );
  };

  return (
    <div>
      <aside className="pb-2 d-flex mt-n2" style={{ gap: 16 }}>
        {allowTracks && <PohCheckbox label="Треки" onChange={setIsLines} checked={isLines} />}
        <PohCheckbox label="Места" onChange={setIsPoints} checked={isPoints} />
        <span className="ms-auto" />
        <PohCheckbox label="Только учтенные" onChange={setIsInDistance} checked={isInDistance} />
      </aside>

      <div style={{ overflowY: 'auto', maxHeight: 400 }}>
        <PohList
          data={data.filter(filterFunc).map((fa) => ({
            key: fa.id,
            action: true,
            content: (
              <span className="d-flex">
                <span style={{ color: fa.color }}>
                  {fa.type === RouteObjectType.Line ? <SlashLg /> : <GeoAlt />}
                </span>
                &nbsp;&nbsp; &nbsp;
                {fa.is_in_distance ? (
                  <span>{fa.name}</span>
                ) : (
                  <del className="text-muted">{fa.name}</del>
                )}
                &nbsp;
                {fa.type === RouteObjectType.Line && fa.distance > 0 && (
                  <PohBadge className="ms-auto">{formatDistance(fa.distance)}</PohBadge>
                )}
              </span>
            ),
            onClick: () => onSelect(fa),
          }))}
        />
      </div>
    </div>
  );
};

export default RouteObjectSelectModal;
