import { get, handleApiError } from '@helpers/httpClient';

import { mapFoodActFront } from '../@mappers/food.mapper';
import { IBaseFoodAct } from '../@types/hiking.baseTypes';

export async function getFoodActs(): Promise<IBaseFoodAct[]> {
  const res = await get('/ajax/food/food_acts_list.php').then(handleApiError);
  return res.map(mapFoodActFront);
}
